#include <stdio.h>

int weights[] = {1, 3, 4, 5};
int values[] = {1, 4, 5, 7};

int best(int i, int capacity) {
    if (i == 4) {
        return 0;
    }
    int skip = best(i + 1, capacity);
    int take = 0;
    if (weights[i] <= capacity) {
        take = values[i] + best(i + 1, capacity - weights[i]);
    }
    return take > skip ? take : skip;
}

int main() {
    printf("%d\n", best(0, 7));
    return 0;
}

