#include <stdio.h>

int main() {
    int weights[] = {1, 3, 4, 5};
    int values[] = {1, 4, 5, 7};
    int dp[8] = {0};
    for (int i = 0; i < 4; i++) {
        for (int w = 7; w >= weights[i]; w--) {
            int take = dp[w - weights[i]] + values[i];
            if (take > dp[w]) {
                dp[w] = take;
            }
        }
    }
    printf("%d\n", dp[7]);
    return 0;
}
